# Re-check the EDUCATIONAL_INSTITUTION filter and geometry-type distribution before accepting an empty polygon result.
spatial_educational_filter_recheck_query = text("""
SELECT
    category::text AS category,
    geometry_type::text AS geometry_type,
    COUNT(*) AS feature_count,
    COUNT(*) FILTER (WHERE geometry IS NOT NULL) AS nonnull_geometry_count,
    COUNT(*) FILTER (WHERE ST_IsValid(geometry)) AS valid_geometry_count
